const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  const key = Object.keys(bin).find(k => String(bin[k].mimeType || '').includes('pdf') || String(bin[k].fileName || '').toLowerCase().endsWith('.pdf'));
  if (!key) continue;
  const j = item.json;
  out.push({
    json: { message_id: String(j.messageId || ((j.subject || '') + '|' + (j.date || ''))), betreff: j.subject || '', mail_datum: j.date || '' },
    binary: { data: bin[key] }
  });
}
return out;

const zone = 'Europe/Berlin';
const zahl = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const out = [];
$input.all().forEach((item, i) => {
  const bon = $('Bon vorbereiten').itemMatching(i).json;
  const c = item.json.choices && item.json.choices[0] && item.json.choices[0].message ? String(item.json.choices[0].message.content || '') : '';
  const s = c.includes('</think>') ? c.split('</think>').pop() : c;
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a < 0 || b < 0) throw new Error('KI-Antwort enthält kein JSON: ' + s.slice(0, 300));
  const data = JSON.parse(s.slice(a, b + 1));
  const kaufdatum = /^\d{4}-\d{2}-\d{2}$/.test(String(data.kaufdatum || '')) ? data.kaufdatum : bon.kaufdatum;
  const kauf = DateTime.fromISO(kaufdatum, { zone });
  for (const art of (data.artikel || [])) {
    const tage = Math.max(0, Math.round(Number(art.haltbarkeit_tage) || 7));
    const einheit = ['g', 'ml', 'stk'].includes(String(art.einheit).toLowerCase()) ? String(art.einheit).toLowerCase() : 'stk';
    const nw = art.naehrwerte_100g || {};
    out.push({ json: {
      name: String(art.name || art.bon_text || 'Unbekannt').trim(),
      bon_text: String(art.bon_text || ''),
      off_suche: String(art.off_suche || art.name || ''),
      frischware: art.frischware === true,
      kategorie: String(art.kategorie || 'Sonstiges'),
      menge: Number(art.menge) || 1,
      einheit,
      packungen: Number(art.packungen) || 1,
      menge_geschaetzt: art.menge_geschaetzt === true,
      gramm_pro_stk: zahl(art.gramm_pro_stk),
      ki_kcal_100: zahl(nw.kcal), ki_protein_100: zahl(nw.protein), ki_fett_100: zahl(nw.fett), ki_kh_100: zahl(nw.kh),
      lagerort: String(art.lagerort || 'Vorratsschrank'),
      haltbarkeit_tage: tage,
      kaufdatum: kauf.toISODate(),
      mhd: kauf.plus({ days: tage }).toISODate(),
      bon_id: bon.message_id,
      bon_summe: Number(data.summe) || 0
    } });
  }
});
return out;

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9äöüß%,.]+/g, ' ').trim();
const arts = $('REWE-Daten übernehmen').all().map(i => i.json);
const prods = $('Grocy-Produkte laden').all().map(i => i.json).filter(p => p && p.id);
const qus = $('Grocy-Einheiten laden').all().map(i => i.json).filter(p => p && p.id);
const locs = $('Grocy-Lagerorte laden').all().map(i => i.json).filter(p => p && p.id);
const quId = n => (qus.find(q => norm(q.name) === norm(n)) || {}).id;
const quIds = { g: quId('Gramm'), ml: quId('Milliliter'), stk: quId('Stück') };
if (!quIds.g || !quIds.ml || !quIds.stk) throw new Error('In Grocy fehlen die Einheiten Gramm/Milliliter/Stück – bitte einmal den Workflow „Vorrat · Grocy einrichten“ ausführen.');
const quCode = { [quIds.g]: 'g', [quIds.ml]: 'ml', [quIds.stk]: 'stk' };
const locId = n => (locs.find(l => norm(l.name) === norm(n)) || locs[0] || {}).id;
const byName = {};
for (const p of prods) byName[norm(p.name)] = p;

return arts.map(a => {
  const p = byName[norm(a.name)];
  let menge = a.menge;
  let einheit = a.einheit;
  if (p) {
    const pe = quCode[p.qu_id_stock];
    if (pe && pe !== einheit) {
      if (pe === 'g' && einheit === 'stk' && a.gramm_pro_stk) menge = a.menge * a.gramm_pro_stk;
      else if (pe === 'stk' && einheit === 'g' && a.gramm_pro_stk) menge = Math.max(1, Math.round(a.menge / a.gramm_pro_stk));
      einheit = pe;
    }
  }
  return { json: { ...a, product_id: p ? p.id : null, menge, einheit, qu_id: quIds[einheit], location_id: locId(a.lagerort) } };
});

const a = $('Produkte zuordnen').item.json;
// REWE-Treffer: Nährwerte aus den REWE-Produktdaten (sonst KI-Schätzung), Barcode als off_code
if (a.rewe_product_id) {
  const z = v => (v === null || v === undefined || isNaN(Number(v))) ? null : Math.round(Number(v) * 10) / 10;
  const n = a.rewe_naehrwerte;
  const kcal = n ? z(n.kcal) : z(a.ki_kcal_100);
  const faktor = a.einheit === 'stk' ? (a.gramm_pro_stk || 100) / 100 : 0.01;
  const preis = a.rewe_preis != null ? Number(a.rewe_preis).toFixed(2).replace('.', ',') + ' €' : '';
  return { json: { ...a, kcal_100: kcal, protein_100: n ? z(n.protein) : z(a.ki_protein_100), fett_100: n ? z(n.fett) : z(a.ki_fett_100),
    kh_100: n ? z(n.kh) : z(a.ki_kh_100), nutriscore: '', nova: null, off_code: a.ean || '', off_name: ((a.marke ? a.marke + ' ' : '') + a.name).trim(),
    quelle: n ? 'rewe' : 'ki-schaetzung', kcal_pro_einheit: kcal == null ? 0 : Math.round(kcal * faktor * 100) / 100,
    beschreibung: ['REWE', a.marke, preis, 'REWE-ID ' + a.rewe_product_id, a.ean ? 'EAN ' + a.ean : '', n ? '' : 'Nährwerte geschätzt'].filter(Boolean).join(' · ') } };
}
const hits = ($json && Array.isArray($json.products)) ? $json.products : [];
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9äöüß]+/g, ' ').trim();
const woerter = norm(a.name).split(' ').filter(w => w.length > 2);
let best = null;
let bestScore = 0;
for (const p of hits) {
  const n = p.nutriments || {};
  if (n['energy-kcal_100g'] == null) continue;
  const pn = norm((p.product_name || '') + ' ' + (p.brands || ''));
  const score = woerter.length ? woerter.filter(w => pn.includes(w)).length / woerter.length : 0;
  if (score > bestScore) { best = p; bestScore = score; }
}
const ok = !!best && bestScore >= (a.frischware ? 1 : 0.5);
const n = ok ? best.nutriments : {};
const r1 = v => (v === null || v === undefined || isNaN(Number(v))) ? null : Math.round(Number(v) * 10) / 10;
let menge = a.menge;
if (ok && a.menge_geschaetzt && ['g', 'ml'].includes(a.einheit) && Number(best.product_quantity) > 0) menge = Number(best.product_quantity) * (a.packungen || 1);
const kcal_100 = ok ? r1(n['energy-kcal_100g']) : r1(a.ki_kcal_100);
const faktor = a.einheit === 'stk' ? (a.gramm_pro_stk || 100) / 100 : 0.01;
const hinweis = ok ? ['Nutri-Score ' + String(best.nutriscore_grade || '?').toUpperCase(), best.nova_group ? 'NOVA ' + best.nova_group : '', 'OFF ' + best.code].filter(Boolean).join(' · ') : 'Nährwerte geschätzt';
return { json: {
  ...a,
  menge,
  kcal_100,
  protein_100: ok ? r1(n.proteins_100g) : r1(a.ki_protein_100),
  fett_100: ok ? r1(n.fat_100g) : r1(a.ki_fett_100),
  kh_100: ok ? r1(n.carbohydrates_100g) : r1(a.ki_kh_100),
  nutriscore: ok && best.nutriscore_grade && best.nutriscore_grade.length === 1 ? best.nutriscore_grade.toUpperCase() : '',
  nova: ok && best.nova_group ? Number(best.nova_group) : null,
  off_code: ok ? String(best.code || '') : '',
  off_name: ok ? String((best.brands ? best.brands + ' ' : '') + (best.product_name || '')) : '',
  quelle: ok ? 'openfoodfacts' : 'ki-schaetzung',
  kcal_pro_einheit: kcal_100 == null ? 0 : Math.round(kcal_100 * faktor * 100) / 100,
  beschreibung: hinweis
} };

const arts = $('Alle Artikel').all().map(i => i.json);
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const heute = DateTime.now().setZone('Europe/Berlin').startOf('day');
const byBon = {};
for (const a of arts) (byBon[a.bon_id] = byBon[a.bon_id] || []).push(a);
return Object.keys(byBon).map(id => {
  const l = byBon[id].sort((x, y) => String(x.mhd).localeCompare(String(y.mhd)));
  const datum = DateTime.fromISO(l[0].kaufdatum).setLocale('de');
  const zeilen = l.map(a => {
    const m = DateTime.fromISO(a.mhd).setLocale('de');
    const tage = Math.round(m.diff(heute, 'days').days);
    return '• ' + esc(a.name) + ' – ' + a.menge + ' ' + a.einheit + ' · ca. bis ' + m.toFormat('ccc dd.LL.') + (tage <= 2 ? ' ⚠️' : '') + (a.nutriscore ? ' · NS ' + a.nutriscore : '');
  });
  const neu = l.filter(a => a.quelle).length;
  const off = l.filter(a => a.quelle === 'openfoodfacts').length;
  const text = '🧾 <b>REWE-Einkauf vom ' + datum.toFormat('dd.LL.yyyy') + ' in Grocy gebucht</b>\n'
    + l.length + ' Lebensmittel' + (l[0].bon_summe ? ' · ' + l[0].bon_summe.toFixed(2).replace('.', ',') + ' €' : '')
    + (neu ? ' · ' + neu + ' neue Produkte (' + off + ' mit OpenFoodFacts-Nährwerten)' : '') + '\n\n'
    + zeilen.join('\n')
    + '\n\n<i>Haltbarkeit ist geschätzt. Korrigieren z.B. mit: „Joghurt hält bis 15.10.“</i>\nRezeptideen kommen gleich 🍳';
  return { json: { message_id: id, datum: l[0].kaufdatum, summe: l[0].bon_summe || 0, anzahl_artikel: l.length, text } };
});

// Pro Bon eine Anfrage an den REWE-Dienst: Bontext + Kassentexte der KI-Artikel (Reihenfolge bleibt erhalten)
const arts = $('Artikel aufbereiten').all().map(i => i.json);
const pdfs = $('PDF-Anhang finden').all().map(i => i.json);
const texte = $('Text aus PDF lesen').all().map(i => i.json);
const textNach = {};
pdfs.forEach((p, i) => { textNach[p.message_id] = String((texte[i] || {}).text || ''); });
const bons = {};
for (const a of arts) (bons[a.bon_id] = bons[a.bon_id] || []).push(a);
return Object.entries(bons).map(([bon_id, l]) => ({ json: { bon_id, body: { bon_id, text: textNach[bon_id] || '', kaufdatum: l[0].kaufdatum, artikel_texte: l.map(a => a.bon_text || a.name) } } }));

// Sichere REWE-Treffer: exakter Produktname, Marke, Barcode, Packungsgröße und REWE-Nährwerte übernehmen.
// Unsichere Zeilen behalten die KI-Werte und bekommen nach dem Einbuchen eine Rückfrage per Telegram.
// Wasser wird nie erfasst
const istWasser = t => /wasser|sprudel/i.test(String(t || '')) && !/melone|kokos|rosen|orangenbl/i.test(String(t || ''));
const arts = $('Artikel aufbereiten').all().map(i => i.json);
const anfragen = $('REWE-Anfrage bauen').all().map(i => i.json);
const antworten = $input.all().map(i => i.json);
const nachBon = {};
anfragen.forEach((a, i) => { nachBon[a.bon_id] = antworten[i] || {}; });
const zaehler = {};
return arts.map(a => {
  const erg = nachBon[a.bon_id] || {};
  const idx = (zaehler[a.bon_id] = (zaehler[a.bon_id] ?? -1) + 1);
  const z = Array.isArray(erg.artikel) ? erg.artikel[idx] : null;
  if (!z) return { json: { ...a, rewe_status: 'keine' } };
  const basis = { ...a, rewe_status: z.status, rewe_zeile_id: z.zeile_id, rewe_kandidaten: z.kandidaten || [], einzelpreis: z.einzelpreis };
  const p = z.produkt;
  if (z.status !== 'sicher' || !p) return { json: basis };
  const anzahl = z.gewicht_kg ? 1 : (z.anzahl || a.packungen || 1);
  let menge = a.menge, einheit = a.einheit;
  if (z.gewicht_kg) { menge = Math.round(z.gewicht_kg * 1000); einheit = 'g'; }
  else if (p.size_value && ['g', 'ml'].includes(p.size_unit)) { menge = p.size_value * anzahl; einheit = p.size_unit; }
  else if (p.size_unit === 'Stück' && p.size_value) { menge = p.size_value * anzahl; einheit = 'stk'; }
  const nw = p.kcal_100 != null ? { kcal: p.kcal_100, protein: p.protein_100, fett: p.fett_100, kh: p.kh_100 } : null;
  return { json: { ...basis, name: p.name, marke: p.brand || '', rewe_product_id: p.rewe_product_id, ean: p.ean || '',
    menge, einheit, packungen: anzahl, menge_geschaetzt: false, rewe_naehrwerte: nw, rewe_preis: p.price } };
}).filter(i => !istWasser((i.json.bon_text || '') + ' ' + (i.json.name || '')));

// Für unsichere Bonzeilen: „Welches Produkt war …?“ mit bis zu 3 Vorschlägen + „Keins davon“ als Buttons.
// callback_data: bon:<zeile_id>:<rewe_product_id oder 0>:<grocy product_id>:<gebuchte Menge> (für die Mengenkorrektur)
const chat_id = String($('Profil laden').first().json.chat_id || '');
if (!chat_id) return [];
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const euro = n => n == null ? '' : Number(n).toFixed(2).replace('.', ',') + ' €';
const kurz = (s, n) => s.length > n ? s.slice(0, n - 1) + '…' : s;
const offen = $('Alle Artikel').all().map(i => i.json).filter(a => a.rewe_status === 'unsicher' && a.rewe_zeile_id && (a.rewe_kandidaten || []).length);
return offen.slice(0, 10).map(a => {
  const k = a.rewe_kandidaten.slice(0, 3);
  const item = { chat_id, anzahl: k.length, keins: `bon:${a.rewe_zeile_id}:0:${a.product_id || 0}:${a.menge}`,
    text: `🤔 Welches Produkt war „<b>${esc(a.bon_text)}</b>“ (${euro(a.einzelpreis)})?\nEingebucht ist es erst mal als „${esc(a.name)}“.` };
  k.forEach((p, i) => {
    item['k' + (i + 1) + '_text'] = kurz(`${p.name} · ${euro(p.price)}`, 60);
    item['k' + (i + 1) + '_data'] = `bon:${a.rewe_zeile_id}:${p.rewe_product_id}:${a.product_id || 0}:${a.menge}`;
  });
  return { json: item };
});
